
import type { PaymentClientActionInput } from './PaymentClientActionInput.js';
import type { PendingPaymentActionSubjectInput } from './PendingPaymentActionSubjectInput.js';

/** Client-side action required before continuing a payment. Resume an order through PayOrder with order_payment_attempt_id, or continue a standalone PaymentIntent through its confirm endpoint without a replacement credential. */ export type PendingPaymentActionInput = { /** Product-level action type. payment_authentication applies to a payment leg; payment_method_authentication applies to saving a future-billing payment method. */ "action_type": "payment_authentication" | "payment_method_authentication"; /** Direct browser authority required to finish this action before continuing through Flint. Unlike collection guidance, this payload includes a client secret. */ "client_action": PaymentClientActionInput; /** Stable Flint action ID. Use this to deduplicate a repeated action projection while resuming an attempt. */ "pending_action_id": string; /** The attempt subject that requires browser action. Exactly one of payment_intent or setup_payment_source is present. */ "subject": PendingPaymentActionSubjectInput; };
